const REGIONAL_VALIDITY_DAYS = 365;
const MANAGED_RUNTIME_API_BASE_BY_ENVIRONMENT = Object.freeze({
  PROD: "https://padlhub.su/api",
  // Intentionally unbound until a dedicated DEV CUP origin exposes the complete
  // runtime-context/entitlement/activation contract without proxying production.
  DEV: null,
});

const OUTPUT_HTTP = 0;
const OUTPUT_MONGO_FIND = 1;
const OUTPUT_MONGO_INSERT = 2;
const OUTPUT_MONGO_UPDATE = 3;
const OUTPUT_FINAL = 4;
const OUTPUT_DEBUG = 5;
const OUTPUT_MANAGED_POLICY = 6;

const emit = (index, value = msg) => {
  if (index === OUTPUT_MONGO_INSERT && ctx?.trialExercise && ctx.trialInsertGrant !== true) {
    ctx.trialSavedInsert = { step: ctx.step, payload: value.payload };
    const gated = trialBeginGate(ctx, ctx.trialExercise, "insert");
    if (gated) return gated;
    delete ctx.trialSavedInsert;
  }
  if (ctx) delete ctx.trialInsertGrant;
  if (value._subscriptionBooking?.caller === "split_create_readonly_preflight"
    && ([2, 3].includes(index) || (index === 1 && !lk1ReadonlyLookup(value)) || (index === 0 && !preflightReadOnlyHttp(value)))) {
    value.statusCode = 409;
    value.payload = {
      error: "Предварительная проверка не разрешает операции базы",
      details: { code: "SUBSCRIPTION_CREATE_PREFLIGHT_WRITE_BLOCKED" }
    };
    return [null, null, null, null, value, null, null];
  }
  if (value._subscriptionBooking?.managedCreateBinding && index === OUTPUT_DEBUG) return null;
  if (value._subscriptionBooking?.trainingRegistration && typeof trainingOutput === "function"
    && index !== OUTPUT_FINAL) {
    const restricted = trainingOutput(value._subscriptionBooking, index);
    if (restricted) return restricted;
  }
  const outputs = [null, null, null, null, null, null, null];
  outputs[index] = value;
  return outputs;
};

const isObj = (value) => value && typeof value === "object" && !Array.isArray(value);
const asArray = (value) => (Array.isArray(value) ? value : []);
const toStr = (value) => {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text || null;
};
const normalizeId = (value) => toStr(value)?.toLowerCase() || null;
const normalizePhone = (value) => {
  const digits = String(value || "").replace(/\D/g, "");
  if (!digits) return null;
  if (digits.length === 10) return `7${digits}`;
  if (digits.length === 11 && digits.startsWith("8")) return `7${digits.slice(1)}`;
  return digits;
};
const normalizeDate = (value) => {
  const matched = String(value || "").trim().match(/^(\d{4})-(\d{2})-(\d{2})/);
  return matched ? `${matched[1]}-${matched[2]}-${matched[3]}` : null;
};
const normalizeMarker = (value) => String(value || "")
  .trim()
  .toLowerCase()
  .replace(/ё/g, "е")
  .replace(/[^a-z0-9а-я]+/gi, "");
const isHttpOk = (status) => Number(status) >= 200 && Number(status) < 300;
const readGlobal = (key) => {
  try {
    return toStr(global.get(key));
  } catch (_) {
    return null;
  }
};

const readManagedRuntimeEnvironment = () => {
  const configured = readGlobal(MANAGED_RUNTIME_ENVIRONMENT_GLOBAL);
  const environment = configured === null ? null : configured.toUpperCase();
  if (!["DEV", "PROD"].includes(environment)) {
    return { ok: false, code: "MANAGED_SUBSCRIPTION_ENVIRONMENT_INVALID" };
  }
  if (environment !== MANAGED_RUNTIME_EXPECTED_ENVIRONMENT) {
    return { ok: false, environment, code: "MANAGED_SUBSCRIPTION_RUNTIME_CROSS_ENVIRONMENT" };
  }
  return { ok: true, environment };
};

const readManagedRuntimeApiConfig = () => {
  const identity = readManagedRuntimeEnvironment();
  if (!identity.ok) return identity;
  const expectedApiBase = MANAGED_RUNTIME_API_BASE_BY_ENVIRONMENT[identity.environment];
  if (!expectedApiBase) {
    return {
      ok: false,
      environment: identity.environment,
      code: "MANAGED_SUBSCRIPTION_DEV_RUNTIME_ORIGIN_UNBOUND",
    };
  }
  const configuredApiBase = readGlobal("subscriptions_runtime_api_base_url");
  if (!configuredApiBase) {
    return {
      ok: false,
      environment: identity.environment,
      code: "MANAGED_SUBSCRIPTION_RUNTIME_NOT_CONFIGURED",
    };
  }
  let parsed;
  try {
    parsed = new URL(configuredApiBase);
  } catch (_) {
    return {
      ok: false,
      environment: identity.environment,
      code: "MANAGED_SUBSCRIPTION_RUNTIME_URL_INVALID",
    };
  }
  const transportAllowed = identity.environment === "PROD"
    ? parsed.protocol === "https:"
    : parsed.protocol === "http:" && parsed.hostname === "127.0.0.1";
  const strictUrl = transportAllowed
    && !parsed.username
    && !parsed.password
    && !parsed.search
    && !parsed.hash
    && parsed.pathname === "/api"
    && parsed.href === expectedApiBase;
  if (!strictUrl) {
    return {
      ok: false,
      environment: identity.environment,
      code: "MANAGED_SUBSCRIPTION_RUNTIME_CROSS_ENVIRONMENT",
    };
  }
  return { ok: true, environment: identity.environment, apiBase: expectedApiBase };
};

const readManagedDevCanaries = () => {
  let configured;
  try {
    configured = global.get(MANAGED_DEV_CANARY_GLOBAL);
  } catch (_) {
    configured = undefined;
  }
  if (configured === undefined || configured === null || configured === "") {
    return { ok: true, clientSubscriptionIds: [] };
  }
  if (typeof configured === "string") {
    const text = configured.trim();
    if (!text) return { ok: true, clientSubscriptionIds: [] };
    try {
      configured = JSON.parse(text);
    } catch (_) {
      return { ok: false, code: "MANAGED_SUBSCRIPTION_DEV_CANARY_CONFIG_INVALID" };
    }
  }
  if (!Array.isArray(configured) || ![0, 2].includes(configured.length)) {
    return { ok: false, code: "MANAGED_SUBSCRIPTION_DEV_CANARY_CONFIG_INVALID" };
  }
  const normalized = configured.map(normalizeId);
  if (normalized.some((value) => !value || !UUID_PATTERN.test(value))
    || new Set(normalized).size !== normalized.length) {
    return { ok: false, code: "MANAGED_SUBSCRIPTION_DEV_CANARY_CONFIG_INVALID" };
  }
  return { ok: true, clientSubscriptionIds: normalized };
};

const managedEnvironmentAllowsSubscription = (clientSubscriptionId) => {
  const identity = readManagedRuntimeEnvironment();
  if (!identity.ok) return identity;
  if (identity.environment === "PROD") return { ok: true, environment: "PROD", allowed: true };
  const canaries = readManagedDevCanaries();
  if (!canaries.ok) return canaries;
  return {
    ok: true,
    environment: "DEV",
    allowed: canaries.clientSubscriptionIds.includes(normalizeId(clientSubscriptionId)),
  };
};

const readManagedEnforcementAllowlist = () => {
  let configured;
  try {
    configured = global.get(MANAGED_ENFORCEMENT_ALLOWLIST_GLOBAL);
  } catch (_) {
    configured = undefined;
  }
  if (configured === undefined || configured === null || configured === "") {
    return { ok: true, productIds: [] };
  }
  if (typeof configured === "string") {
    const text = configured.trim();
    if (!text) return { ok: true, productIds: [] };
    try {
      configured = JSON.parse(text);
    } catch (_) {
      return { ok: false, code: "MANAGED_SUBSCRIPTION_ENFORCEMENT_CONFIG_INVALID" };
    }
  }
  if (!Array.isArray(configured)) {
    return { ok: false, code: "MANAGED_SUBSCRIPTION_ENFORCEMENT_CONFIG_INVALID" };
  }
  const normalized = [];
  for (const value of configured) {
    const productId = normalizeId(value);
    if (!productId || !UUID_PATTERN.test(productId)) {
      return { ok: false, code: "MANAGED_SUBSCRIPTION_ENFORCEMENT_CONFIG_INVALID" };
    }
    normalized.push(productId);
  }
  return { ok: true, productIds: [...new Set(normalized)].sort() };
};

const responseHeaders = () => ({
  "Content-Type": "application/json; charset=utf-8",
  "Cache-Control": "no-store",
  "Access-Control-Allow-Origin": "*",
});

const finishError = (ctx, statusCode, error, details) => {
  lkDiagnostic({ code: details?.code, httpStatus: statusCode, outcome: "refused" });
  msg._subscriptionBooking = ctx;
  msg.statusCode = statusCode;
  msg.headers = responseHeaders();
  msg.payload = { error, details: details || null };
  delete msg.error;
  return emit(OUTPUT_FINAL);
};

const finishPending = (ctx, message, details) => {
  lkDiagnostic({ code: "OUTCOME_UNKNOWN", outcome: "outcome_unknown" });
  msg._subscriptionBooking = ctx;
  msg.statusCode = 202;
  msg.headers = responseHeaders();
  msg.payload = {
    ok: true,
    state: "PENDING_CONFIRMATION",
    operationId: ctx.operationId,
    exerciseId: ctx.exerciseId,
    message: message || "Запись принята и ожидает подтверждения Viva",
    details: details || null,
  };
  delete msg.error;
  return emit(OUTPUT_FINAL);
};

const finishConfirmed = (ctx, bookingId, statusCode = 200) => {
  if (!ctx.lk1) { const completion = tournamentAdmissionComplete(ctx, bookingId); if (completion) return completion; }
  const normalizedBookingId = toStr(bookingId);
  if (!normalizedBookingId) {
    return finishPending(ctx, "Запись найдена в Viva без устойчивого bookingId и требует сверки");
  }
  msg._subscriptionBooking = ctx;
  msg.statusCode = statusCode;
  msg.headers = responseHeaders();
  msg.payload = {
    ok: true,
    state: "CONFIRMED",
    operationId: ctx.operationId,
    exerciseId: ctx.exerciseId,
    bookingId: normalizedBookingId,
    clientSubscriptionId: ctx.clientSubscriptionId,
  };
  delete msg.error;
  return emit(OUTPUT_FINAL);
};

const finishReleased = (ctx, details = null) => {
  msg._subscriptionBooking = ctx;
  msg.statusCode = 200;
  msg.headers = responseHeaders();
  msg.payload = {
    ok: true,
    state: "RELEASED",
    operationId: ctx.operationId,
    bookingId: ctx.releaseBookingId,
    details,
  };
  delete msg.error;
  return emit(OUTPUT_FINAL);
};

// Bind owner-less Viva self-list rows to the exact authenticated confirmation request.
const lk1EventMoneyBooking = (ctx) => ctx.caller === "http"
  && ((ctx.managedAction === "BOOK_GROUP_TRAINING" && ctx.category === "group_training")
    || (ctx.managedAction === "BOOK_TOURNAMENT" && ctx.category === "tournament"))
  && ctx.lk1?.decision?.subscriptionVisitCount === 0
  && ctx.lk1.decision.benefit?.kind === "PERCENT_DISCOUNT"
  && Number.isSafeInteger(ctx.lk1.decision.benefit.finalPriceMinor)
  && ctx.lk1.decision.benefit.finalPriceMinor >= 0;
const lk1BindConfirmationRead = (ctx, step, method, url, headers) => {
  delete ctx.lk1ConfirmationRead;
  if (ctx.lk1 && step === "confirmation_bookings" && method === "GET"
    && url === `${VIVA_API_BASE}/end-user/api/v2/${ctx.tenantKey}/bookings?size=1000`
    && headers.Authorization === ctx.authHeader) {
    ctx.lk1ConfirmationRead = {
      url, actorClientId: ctx.actorClientId,
      operationId: ctx.operationId, operationKey: ctx.operationKey, authHeader: ctx.authHeader
    };
  }
};
const lk1BookingSelfReadback = (ctx) => {
  const proof = ctx.lk1ConfirmationRead;
  delete ctx.lk1ConfirmationRead;
  const url = `${VIVA_API_BASE}/end-user/api/v2/${ctx.tenantKey}/bookings?size=1000`;
  return Boolean(proof && proof.url === url && proof.actorClientId === ctx.actorClientId
    && proof.operationId === ctx.operationId && proof.operationKey === ctx.operationKey
    && typeof ctx.authHeader === "string" && /^Bearer\s+\S+$/i.test(ctx.authHeader)
    && proof.authHeader === ctx.authHeader && msg.method === "GET" && msg.url === url
    && (msg.responseUrl === undefined || msg.responseUrl === url)
    && msg.followRedirects === false && msg.maxRedirects === 0);
};
const lk1BookingOwnerMatches = (booking, actorClientId) => {
  if (typeof actorClientId !== "string" || !actorClientId.trim()) return false;
  const aliases = [];
  for (const key of ["clientId", "playerId", "userId"]) {
    if (Object.prototype.hasOwnProperty.call(booking, key)) aliases.push(booking[key]);
  }
  if (Object.prototype.hasOwnProperty.call(booking, "client")) {
    if (!isObj(booking.client)) return false;
    for (const key of ["id", "clientId"]) {
      if (Object.prototype.hasOwnProperty.call(booking.client, key)) aliases.push(booking.client[key]);
    }
  }
  // The authenticated self-list omits owner fields; explicit invalid/conflicting echoes fail.
  return aliases.every(value => typeof value === "string" && value.trim()
    && normalizeId(value) === normalizeId(actorClientId));
};
const lk1BookingUnpaidOnPlace = (booking) => booking.paymentType === "ON_PLACE"
  && (booking.paymentMethod === undefined || booking.paymentMethod === "ON_PLACE")
  && !isSubscriptionBooking(booking)
  && (booking.transactionStatus === undefined || booking.transactionStatus === null)
  && (booking.pendingPayments === undefined || (Array.isArray(booking.pendingPayments) && booking.pendingPayments.length === 0));

const finishFullPriceFallback = (ctx, blockers) => {
  msg._subscriptionBooking = ctx;
  msg.statusCode = 200;
  msg.headers = responseHeaders();
  msg.payload = {
    ok: true,
    state: "FULL_PRICE_WITHOUT_SUBSCRIPTION",
    operationId: ctx.operationId,
    exerciseId: ctx.exerciseId,
    clientSubscriptionId: ctx.clientSubscriptionId,
    blockers: asArray(blockers),
  };
  delete msg.error;
  return emit(OUTPUT_FINAL);
};

const finishManagedCreatePreflight = (ctx, state = "PREFLIGHT_ATTEMPT_BOUND") => {
  msg._subscriptionBooking = ctx;
  msg.statusCode = 200;
  msg.headers = responseHeaders();
  msg.payload = {
    ok: true,
    state,
    operationId: ctx.operationId,
    exerciseId: ctx.exerciseId,
    clientSubscriptionId: ctx.clientSubscriptionId,
  };
  delete msg.error;
  return emit(OUTPUT_FINAL);
};

const prepareHttp = (ctx, step, method, url, payload, headers = {}) => {
  if (ctx.caller === "split_create_readonly_preflight" && !preflightReadOnlyHttp({
    method, url, payload, _subscriptionBooking: { ...ctx, step },
  })) {
    return finishError(ctx, 409, "Предварительная проверка не разрешает запись", {
      code: "SUBSCRIPTION_CREATE_PREFLIGHT_WRITE_BLOCKED",
    });
  }
  lk1BindConfirmationRead(ctx, step, method, url, headers);
  ctx.step = step;
  msg._subscriptionBooking = ctx;
  msg.method = method;
  msg.url = url;
  msg.headers = headers;
  msg.payload = payload;
  msg.followRedirects = false;
  msg.maxRedirects = 0;
  delete msg.error;
  // A request's provenance must be its own response: Node-RED sets `msg.responseUrl` on
  // every reply and the gateway/tariff checks compare it with the URL they asked for.
  // Leaving the previous step's value in place made those checks fail on a stale URL
  // (`LK1_EVENT_TARIFF_UNVERIFIED` on every group training and tournament).
  delete msg.responseUrl;
  delete msg.statusCode;
  return emit(OUTPUT_HTTP);
};

const prepareManagedHttp = (ctx, step, method, url, payload, headers = {}) => {
  const output = prepareHttp(ctx, step, method, url, payload, headers);
  msg.followRedirects = false;
  msg.maxRedirects = 0;
  msg.requestTimeout = 10000;
  return output;
};

const prepareUserGet = (ctx, step, path) => prepareHttp(
  ctx,
  step,
  "GET",
  `${VIVA_API_BASE}${path}`,
  undefined,
  { Authorization: ctx.authHeader, Accept: "application/json" },
);

const prepareManagedRuntimeContext = (ctx, step = "managed_runtime_context") => {
  if (ctx.managedEnforcement?.enabled !== true
    || ctx.managedEnforcement.exactProductId !== PITER_MANAGED_PRODUCT_ID
    || ctx.planKey !== "piter_friendship") {
    const details = { code: "MANAGED_SUBSCRIPTION_ENFORCEMENT_CONTEXT_INVALID" };
    return step === "managed_runtime_recheck"
      ? prepareFailedUpdate(ctx, 409, "Контекст управляемой подписки изменился до записи", details.code)
      : finishError(ctx, 409, "Контекст управляемой подписки не подтверждён", details);
  }
  const runtimeConfig = readManagedRuntimeApiConfig();
  const integrationToken = readGlobal("subscriptions_runtime_context_integration_token");
  if (!runtimeConfig.ok || Buffer.byteLength(integrationToken || "", "utf8") < 32) {
    return finishError(ctx, 503, "Контур правил подписки временно недоступен", {
      code: runtimeConfig.code || "MANAGED_SUBSCRIPTION_RUNTIME_NOT_CONFIGURED",
    });
  }
  return prepareManagedHttp(
    ctx,
    step,
    "POST",
    `${runtimeConfig.apiBase}/internal/subscriptions/runtime-context`,
    { clientSubscriptionId: ctx.clientSubscriptionId },
    {
      Authorization: ctx.authHeader,
      "X-Subscriptions-Integration-Token": integrationToken,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
  );
};

const managedActivationConfig = () => {
  const runtimeConfig = readManagedRuntimeApiConfig();
  return {
    ...runtimeConfig,
    integrationToken: readGlobal("subscriptions_activation_integration_token"),
  };
};

const validManagedActivationConfig = (config, ctx = null) => (
  config.ok === true
  && (!ctx || config.environment === (ctx.managedEnforcement?.environment || ctx.managedEnvironment))
  && Buffer.byteLength(config.integrationToken || "", "utf8") >= 32
);

const managedActivationConfigured = () => {
  const config = managedActivationConfig();
  return validManagedActivationConfig(config);
};

const managedEntitlementConfig = () => {
  const runtimeConfig = readManagedRuntimeApiConfig();
  return {
    ...runtimeConfig,
    integrationToken: readGlobal("subscriptions_entitlement_integration_token"),
  };
};

const validManagedEntitlementConfig = (config, ctx = null) => (
  config.ok === true
  && (!ctx || config.environment === (ctx.managedEnforcement?.environment || ctx.managedEnvironment))
  && Buffer.byteLength(config.integrationToken || "", "utf8") >= 32
);

const managedEntitlementHeaders = (ctx, config) => ({
  Authorization: ctx.authHeader,
  "X-Subscriptions-Integration-Token": config.integrationToken,
  "X-Correlation-Id": ctx.operationId,
  "Content-Type": "application/json",
  Accept: "application/json",
});

// Opt-in backend evidence producer. Never copy the key or proof into operation/context storage.
const managedOwnerEvidence = (ctx, kind, providerBookingId) => {
  const unavailable = { ok: false, code: "SUBSCRIPTION_OWNER_EVIDENCE_NOT_CONFIGURED" };
  try {
    const mode = global.get("subscriptions_owner_evidence_enabled");
    if (mode === undefined || mode === null || mode === false || mode === "false") {
      return kind === "PRECREATE_EXPIRED_NOT_DISPATCHED" ? unavailable : { ok: true, headers: {} };
    }
    if (mode !== true && mode !== "true") return unavailable;
    const secret = global.get("subscriptions_owner_evidence_secret");
    const crypto = global.get("crypto");
    if (typeof secret !== "string" || Buffer.byteLength(secret.trim(), "utf8") < 32
      || typeof crypto?.createHmac !== "function") return unavailable;
    const evidence = ctx.ownerBookingReadback;
    const idPattern = /^[A-Za-z0-9][A-Za-z0-9._:-]{2,199}$/;
    const age = Date.now() - Date.parse(evidence?.observedAt);
    const operation = ctx.releaseOperation;
    if (kind === "BOOKING_CANCELLED" && (!operation
      || operation.tenantKey !== ctx.tenantKey || operation.actorClientId !== ctx.actorClientId
      || normalizeId(operation.exerciseId) !== normalizeId(ctx.exerciseId)
      || normalizeId(operation.clientSubscriptionId) !== normalizeId(ctx.clientSubscriptionId)
      || operation.serviceDate !== ctx.serviceDate)) {
      return { ok: false, code: "SUBSCRIPTION_OWNER_EVIDENCE_READBACK_REQUIRED" };
    }
    if (!evidence || evidence.kind !== kind
      || evidence.operationId !== ctx.managedEntitlementOperationId
      || evidence.bookingId !== providerBookingId
      || evidence.tenantKey !== ctx.tenantKey || evidence.actorClientId !== ctx.actorClientId
      || evidence.exerciseId !== ctx.exerciseId || evidence.subscriptionId !== ctx.clientSubscriptionId
      || !idPattern.test(ctx.managedEntitlementOperationId || "")
      || (["PROVIDER_REJECTED", "PRECREATE_EXPIRED_NOT_DISPATCHED"].includes(kind) ? providerBookingId !== null : !idPattern.test(providerBookingId || ""))
      || !Number.isFinite(age) || age < 0 || age > 60_000) {
      return { ok: false, code: "SUBSCRIPTION_OWNER_EVIDENCE_READBACK_REQUIRED" };
    }
    const claims = kind === "CONFIRMED"
      ? { operationId: ctx.managedEntitlementOperationId, providerBookingId, issuedAt: evidence.observedAt }
      : { operationId: ctx.managedEntitlementOperationId, reason: kind, providerBookingId, issuedAt: evidence.observedAt };
    const encoded = Buffer.from(JSON.stringify(claims), "utf8").toString("base64url");
    const prefix = kind === "CONFIRMED" ? "v1" : "release-v1";
    const domain = kind === "CONFIRMED" ? "owner-evidence:v1" : "owner-evidence:release:v1";
    const mac = crypto.createHmac("sha256", secret.trim()).update(`${domain}\0${encoded}`).digest("hex");
    return { ok: true, headers: { "X-Subscription-Owner-Evidence": `${prefix}.${encoded}.${mac}` } };
  } catch {
    return unavailable;
  }
};

const recordOwnerReadback = (ctx, kind, bookingId, observedAt = new Date().toISOString()) => {
  ctx.ownerBookingReadback = {
    kind, bookingId, operationId: ctx.managedEntitlementOperationId,
    tenantKey: ctx.tenantKey, actorClientId: ctx.actorClientId,
    exerciseId: ctx.exerciseId, subscriptionId: ctx.clientSubscriptionId,
    observedAt,
  };
};

const ownerEvidenceEnabled = () => {
  try {
    return [true, "true"].includes(global.get("subscriptions_owner_evidence_enabled"));
  } catch { return false; }
};

const managedJoinV2SignerReady = () => {
  try {
    const secret = global.get("subscriptions_owner_evidence_secret");
    return ownerEvidenceEnabled() && typeof secret === "string" && Buffer.byteLength(secret.trim(), "utf8") >= 32
      && typeof global.get("crypto")?.createHmac === "function";
  } catch { return false; }
};
const managedJoinV2MatchesRuntime = ctx => !ctx.managedJoinV2 || (
  ctx.managedEnforcement?.enabled === true && ctx.managedAction === "JOIN_GAME"
  && ctx.managedRuntime?.subscriptionInstanceId === ctx.managedJoinV2.entitlement.subscriptionInstanceId
  && ctx.managedRuntime?.policyDigest === ctx.managedJoinV2.entitlement.expectations.policyDigest
  && ctx.managedRuntime?.policy?.policyVersion === ctx.managedJoinV2.entitlement.expectations.policyVersion
);
const managedJoinV2Pending = ctx => finishPending(ctx, "Управляемая запись требует сверки владельца", {
  code: "MANAGED_JOIN_V2_RECONCILIATION_REQUIRED",
});

const prepareManagedEntitlementReserve = (ctx) => {
  const admission = tournamentAdmissionGate(ctx, "reserve");
  if (admission) return admission;
  if (ctx.lk2LegacyJoin === true || ctx.managedJoinV2RecoveryOnly || ctx.managedJoinV2RecoveryOperation) return managedJoinV2Pending(ctx);
  if (ctx.managedJoinV2 && (!managedJoinV2MatchesRuntime(ctx) || !managedJoinV2SignerReady()
    || ctx.managedJoinV2FreePolicyDigest !== ctx.managedRuntime?.policyDigest)) {
    return managedJoinV2Pending(ctx);
  }
  const config = managedEntitlementConfig();
  if (!validManagedEntitlementConfig(config, ctx)) {
    return prepareFailedUpdate(
      ctx,
      503,
      "Резерв льготы подписки ещё не настроен",
      config.code || "SUBSCRIPTION_ENTITLEMENT_NOT_CONFIGURED",
    );
  }
  return prepareManagedHttp(
    ctx,
    "managed_entitlement_reserve",
    "POST",
    `${config.apiBase}/internal/subscriptions/entitlements/reserve`,
    {
      subscriptionInstanceId: ctx.managedRuntime.subscriptionInstanceId,
      action: ctx.managedAction,
      target: { targetId: ctx.managedCreateBinding?.targetInput.targetId || ctx.exerciseId },
      ...(ctx.managedCreateBinding ? { expectations: ctx.managedCreateBinding.expectations } : {}),
      ...(ctx.managedJoinV2 ? { expectations: ctx.managedJoinV2.entitlement.expectations } : {}),
    },
    {
      ...managedEntitlementHeaders(ctx, config),
      "Idempotency-Key": ctx.operationId,
    },
  );
};

const prepareManagedEntitlementConfirm = (ctx) => {
  const config = managedEntitlementConfig();
  if (!validManagedEntitlementConfig(config, ctx)) {
    return finishPending(ctx, "Запись подтверждена Viva; льгота ожидает подтверждения ЦУП", {
      code: "SUBSCRIPTION_ENTITLEMENT_NOT_CONFIGURED",
    });
  }
  const proof = managedOwnerEvidence(ctx, "CONFIRMED", ctx.confirmedBookingId);
  if (!proof.ok) return finishPending(ctx, "Подтверждение льготы требует доказательства владельца", { code: proof.code });
  return prepareManagedHttp(
    ctx,
    "managed_entitlement_confirm",
    "POST",
    `${config.apiBase}/internal/subscriptions/entitlements/confirm`,
    {
      operationId: ctx.managedEntitlementOperationId,
      providerBookingId: ctx.confirmedBookingId,
    },
    { ...managedEntitlementHeaders(ctx, config), ...proof.headers },
  );
};

const prepareManagedEntitlementRelease = (ctx, reason, providerBookingId = null) => {
  // A created/adopted exercise is an external side effect. Failure is not proof
  // that it is safe to release its reservation, even before booking creation.
  if (ctx.precreatedEntitlementReserved === true) {
    return preparePrecreatedReconciliation(ctx);
  }
  const config = managedEntitlementConfig();
  if (!validManagedEntitlementConfig(config, ctx) || !toStr(ctx.managedEntitlementOperationId)) {
    return finishPending(ctx, "Резерв льготы требует ручной сверки", {
      code: "SUBSCRIPTION_ENTITLEMENT_RELEASE_NOT_CONFIGURED",
    });
  }
  const proof = managedOwnerEvidence(ctx, reason, providerBookingId);
  if (!proof.ok) return finishPending(ctx, "Освобождение льготы требует доказательства владельца", { code: proof.code });
  const payload = {
    operationId: ctx.managedEntitlementOperationId,
    reason,
  };
  if (providerBookingId) payload.providerBookingId = providerBookingId;
  ctx.entitlementReleaseReason = reason;
  return prepareManagedHttp(
    ctx,
    "managed_entitlement_release",
    "POST",
    `${config.apiBase}/internal/subscriptions/entitlements/release`,
    payload,
    { ...managedEntitlementHeaders(ctx, config), ...proof.headers },
  );
};

const validEntitlementDecision = (ctx, decision) => {
  if (!isObj(decision) || decision.decisionKind !== "ENTITLEMENT"
    || decision.policyVersion !== ctx.managedRuntime?.policy?.policyVersion
    || decision.policyDigest !== ctx.managedRuntime?.policyDigest
    || decision.action !== ctx.managedAction
    || normalizeId(decision.target?.targetId) !== normalizeId(ctx.managedCreateBinding?.targetInput.targetId || ctx.exerciseId)
    || normalizeId(decision.target?.stationId) !== normalizeId(ctx.managedCreateBinding?.targetInput.stationId || ctx.managedTarget?.stationId)
    || toStr(decision.target?.eventTypeId) !== toStr(ctx.managedTarget?.externalEventTypeId)
    || toStr(decision.target?.productTypeId) !== toStr(ctx.managedTarget?.productTypeId)
    || Number(decision.target?.durationMinutes) !== Number(ctx.managedTarget?.durationMinutes)
    || finiteDate(decision.target?.startsAt)?.getTime() !== finiteDate(ctx.managedTarget?.startsAt)?.getTime()
    || !Number.isInteger(decision.usageUnits) || decision.usageUnits < 1
    || !isObj(decision.money) || decision.money.currency !== "RUB") return false;
  return [
    decision.money.basePriceMinor,
    decision.money.discountMinor,
    decision.money.surchargeMinor,
    decision.money.finalPriceMinor,
  ].every((value) => value === null || (Number.isSafeInteger(value) && value >= 0))
    && Number.isSafeInteger(decision.money.finalPriceMinor);
};

